import { useState } from 'react';
import { cn } from '@/lib/utils';
import ShiftsList from '../components/shiftsList/ShiftsList';
import ShiftsStatistics from '../components/statistics/ShiftsStatistics';
import HolidaysPage from './holidays/Holidays';

type ShiftsTab = 'shifts' | 'holidays';

export default function ShiftsPage() {
    const [activeTab, setActiveTab] = useState<ShiftsTab>('shifts');

    return (
        <div className="w-full mt-6 mb-20">
            <div className="w-full flex flex-row items-center gap-[1px] mb-6">
                <button
                    type="button"
                    onClick={() => setActiveTab('shifts')}
                    className={cn(
                        'w-full transition-colors text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal rounded-s-lg',
                        {
                            'bg-primery-blue-700': activeTab === 'shifts',
                            'bg-primery-blue-400': activeTab !== 'shifts',
                        },
                    )}
                >
                    الورديات
                </button>
                <button
                    type="button"
                    onClick={() => setActiveTab('holidays')}
                    className={cn(
                        'w-full transition-colors text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal rounded-e-lg',
                        {
                            'bg-primery-blue-700': activeTab === 'holidays',
                            'bg-primery-blue-400': activeTab !== 'holidays',
                        },
                    )}
                >
                    الإجازات
                </button>
            </div>

            {activeTab === 'shifts' && (
                <>
                    <ShiftsStatistics />
                    <ShiftsList />
                </>
            )}
            {activeTab === 'holidays' && <HolidaysPage />}
        </div>
    );
}
