import { z } from 'zod';

export const AddHolidayDialogSchema = z
    .object({
        name: z.string().min(1, 'اسم الإجازة مطلوب'),
        start_date: z.date({ required_error: 'تاريخ البداية مطلوب' }),
        end_date: z.date({ required_error: 'تاريخ النهاية مطلوب' }),
    })
    .refine((d) => d.end_date >= d.start_date, {
        message: 'تاريخ النهاية يجب أن يكون بعد أو يساوي تاريخ البداية',
        path: ['end_date'],
    });

export type AddHolidayDialogFormValues = z.infer<typeof AddHolidayDialogSchema>;
