import StatisticsCards from '@/components/cards/StatisticsCards';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Card } from '@/types/statistics';
import { useEffect, useState } from 'react';
import { shiftsStats } from '../../types/shift.types';

export default function ShiftsStatistics() {
    const [stats, setStats] = useState<shiftsStats | null>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.shifts.dashboard });
                setStats(res.data.data);
            } catch (err) {
                setStats(null);
            }
        };
        fetchStats();
    }, []);

    const am = stats?.by_type?.am ?? stats?.total_active_shifts;
    const pm = stats?.by_type?.pm ?? stats?.total_inactive_shifts;

    const cards: Card[] = [
        { text: 'عدد الورديات', num: stats?.total_shifts, percent: 12 },
        { text: 'ورديات صباحي', num: am, percent: 0 },
        { text: 'ورديات مسائي', num: pm, percent: -0.3 },
        { text: 'أيام الإجازات', num: stats?.total_holidays, percent: -0.3 },
    ];

    return <StatisticsCards cards={cards} numJustifyStart={true} />;
}
